package io.lumine.mythic.lib.skill.result.def;
import io.lumine.mythic.lib.skill.SkillMetadata; import io.lumine.mythic.lib.skill.result.SkillResult; import net.minecraft.entity.Entity; import net.minecraft.server.network.ServerPlayerEntity; import net.minecraft.util.math.Vec3d;
public class VectorSkillResult implements SkillResult { private final Vec3d target; public VectorSkillResult(SkillMetadata m){this.target=m.getTargetLocationOrNull();} public VectorSkillResult(Vec3d target){this.target=target;} public Vec3d getTarget(){return target;} public Vec3d getTargetDirection(ServerPlayerEntity player,Entity entity){if(player==null||entity==null)return Vec3d.ZERO;return entity.getPos().subtract(player.getPos()).normalize();} public boolean isSuccessful(){return target!=null;} }
